def price_with_vat(price, rate):
    return price * (1 + rate)

print(price_with_vat(50, 0.2))

def average(marks):
    return sum(marks) / len(marks)

def letter(avg):
    if avg >= 70:
        return "A"
    elif avg >= 60:
        return "B"
    else:
        return "C or below"

my_avg = average([70, 60, 80])
print(my_avg)
print(letter(my_avg))

def grade(avg):
    if avg >= 70:
        return "A"
    elif avg >= 60:
        return "B"
    elif avg >= 50:
        return "C"
    else:
        return "F"

subjects = ["Maths", "English", "Science"]
marks = []
for subject in subjects:
    mark = float(input(f"{subject} mark: "))
    marks.append(mark)

average = sum(marks) / len(marks)
print(f"Average: {average:.1f}")
print("Grade:", grade(average))

